ruleBookInfo.author:
@js:
// 作者规则 v4：规则作用域无 baseElement，一律用 result(整页HTML) 自解析 jsoup
// 五级兜底：①行首「作者 X/作者：X」全行扫描 ②预览行内「书名 作者：X」③书名内嵌 ④书名by作者 ⑤整页兜底
var NL = String.fromCharCode(10);
var stop = '写文|不易|回复|评论|声明|原创|地址|建议|支持|请到|的话|表示|群里|群号';
var CUT = /[\s（(【\[「《\/、,，]/;
function clean(s) {
  s = String(s);
  s = s.replace(/^\s+/, '').replace(/\s+$/, '');
  s = s.replace(/^[\s:：,，.。、;；~～\-—]+/, '');
  s = s.replace(/[\s:：,，.。、;；~～\-—]+$/, '');
  return s;
}
function pick(t) {
  t = String(t);
  var i = t.search(CUT);
  if (i > 0) t = t.substring(0, i);
  t = clean(t);
  if (!t) return '';
  if (t.length > 18) return '';
  if (new RegExp('^(' + stop + ')$').test(t)) return '';
  if (new RegExp('(写文|不易|群号|原创地址|回复或评论|请到|的话|声明)').test(t)) return '';
  return t;
}
var html = '';
try { html = String(result == null ? '' : result); } catch (e) { html = ''; }
var lines = [];
var title = '';
try {
  var d = Packages.org.jsoup.Jsoup.parse(html);
  var pt = d.select('.preview-text');
  if (pt.size() > 0) {
    var h = String(pt.get(0).html()).replace(/<br\s*\/?>/gi, NL);
    h = String(Packages.org.jsoup.parser.Parser.unescapeEntities(h, true));
    h = h.replace(/<[^>]+>/g, '');
    lines = String(h).split(NL);
  }
  var nm = d.select('.ph-name');
  if (nm.size() > 0) title = String(nm.get(0).text());
} catch (e1) {}
var name = '';
var i;
for (i = 0; i < lines.length; i++) {
  var m = clean(lines[i]).match(/^作\s*者\s*[\s:：]+(.+)$/);
  if (m) { name = pick(m[1]); if (name) break; }
}
if (!name) {
  for (i = 0; i < lines.length; i++) {
    var m2 = clean(lines[i]).match(/^.{0,40}?作\s*者\s*[\s:：]+(.+)$/);
    if (m2) { name = pick(m2[1]); if (name) break; }
  }
}
if (!name) {
  var m3 = clean(title).match(/作\s*者\s*[\s:：]+(.+)$/);
  if (m3) name = pick(m3[1]);
}
if (!name) {
  for (i = 0; i < lines.length && i < 6; i++) {
    var m4 = clean(lines[i]).match(/^.{2,40}?[bB][yY]([^bB\s]{1,16})$/);
    if (m4) { name = pick(m4[1]); if (name) break; }
  }
}
if (!name) {
  var flat = String(html).replace(/<[^>]+>/g, ' ');
  var m5 = flat.match(/作\s*者\s*[\s:：]+\s*([^\s，。；、！？!?*（）()【】\[\]{}《》"']{1,18})/);
  if (m5) name = pick(m5[1]);
}
result = name;

